E|ポエニ戦争|前264〜前146|古代ローマ|3
d|西地中海の覇権をめぐるローマとカルタゴの3回の戦い。第2回ではハンニバルがイタリアに侵入しカンネーの戦いで大勝したが、スキピオがザマの戦い（前202）で破った。第3回でカルタゴは滅亡した。
