r|ローマが地中海の覇権を握り、属州を獲得した（同じころ東方のヘレニズム諸国にも進出）／長い戦争で農地が荒れ、属州からの安い穀物と奴隷が流れこみ、ラティフンディア（奴隷制大農場）が広がって中小農民が没落した／没落農民を救おうとしたグラックス兄弟の改革が失敗し、内乱の1世紀へ
p|ハンニバル
