c|ポエニ戦争後、ラティフンディアの拡大で中小農民が没落し、重装歩兵として戦う市民軍の基盤がくずれた
r|改革は失敗し、閥族派と平民派の対立が激しくなって内乱の1世紀に入った
p|グラックス兄弟
