E|内乱の1世紀|前133〜前27|古代ローマ|3
d|グラックス兄弟の改革からオクタウィアヌスの元首政開始までの内乱の時代。マリウス（平民派）とスラ（閥族派）の争い、同盟市戦争（イタリアの全自由民に市民権）、スパルタクスの反乱（前73〜前71）、第1回・第2回三頭政治が続いた。
c|ポエニ戦争後の中小農民の没落で、市民軍がくずれた／グラックス兄弟の改革の失敗で、閥族派と平民派の対立が激しくなった／マリウスの兵制改革で、無産市民の志願兵が有力者の私兵のようになった
r|カエサルが独裁権を握ったが暗殺された（前44）／アクティウムの海戦（前31）でオクタウィアヌスがアントニウスとクレオパトラを破り、プトレマイオス朝も滅亡（前30）。元首政の開始に至る
