E|元首政の開始|前27|古代ローマ|3
d|オクタウィアヌスが元老院からアウグストゥス（尊厳者）の称号を受け、帝政が始まった。共和政の形式を尊重しながら、市民の中の第一人者（プリンケプス）として実権を握った。
c|内乱の1世紀を終わらせたオクタウィアヌスへの支持
r|約200年間の「ローマの平和（パクス=ロマーナ）」／五賢帝時代（96〜180）に最大領土（トラヤヌス帝）
p|オクタウィアヌス
