E|ミラノ勅令|313|古代ローマ|3
d|コンスタンティヌス帝がキリスト教を公認した勅令。
c|迫害にもかかわらずキリスト教徒が帝国内で増え続けた／帝国の統一を保つためにキリスト教会の支持を得ようとした
