P|イエス|前4頃〜30頃|パレスチナ|3
d|パレスチナで神の愛と隣人愛を説き、ユダヤ教の律法主義を批判した。ローマ総督ピラトによって十字架刑にされた。弟子たちが救世主（キリスト）と信じ、キリスト教が成立した。
