d|後ウマイヤ朝（イベリア半島）、シーア派のファーティマ朝（チュニジアで909年に建国、のちエジプトを征服してカイロを建設）がそれぞれカリフを名のり、3人のカリフが並び立った。946年にはイラン系シーア派のブワイフ朝がバグダードに入り、大アミールとして実権を握った。
c|アッバース朝の成立から時がたち、ハールーン=アッラシードの死後カリフの権威が下がって、地方総督（アミール）や軍人が自立した／ザンジュの乱（黒人奴隷の反乱）などでアッバース朝が弱まった
r|アッバース朝カリフは宗教的な権威だけの存在となった／ブワイフ朝は軍人に土地の徴税権を与えるイクター制を始め、セルジューク朝のバグダード入城後のセルジューク朝が受け継いで発展させた／ファーティマ朝はカイロにアズハル学院を建てた
