E|セルジューク朝のバグダード入城|1055|トルコ、イスラーム帝国|9
d|トルコ系のセルジューク朝のトゥグリル=ベクがブワイフ朝を追ってバグダードに入り、アッバース朝カリフからスルタン（支配者）の称号を受けた。
