d|アイユーブ朝の奴隷軍人（マムルーク）が建てた王朝。都カイロ。アインジャールートの戦い（1260）でモンゴル軍を破り、十字軍の最後の拠点アッコンを奪った（1291）。モンゴルにバグダードを追われたアッバース家のカリフをカイロに迎え、メッカ・メディナを保護した。
c|アイユーブ朝とイェルサレム奪回ののち、アイユーブ朝で奴隷軍人の力が強まっていた
r|モンゴルの西進が止まり、カイロがイスラーム世界の中心都市として繁栄した。カーリミー商人が紅海経由の香辛料などのインド洋・地中海交易で活躍した／1517年、オスマン帝国のエジプト征服で滅亡した
