r|マリ王国の富は「黄金の国」としてヨーロッパにまで知られた。西アフリカの金を求めることは、大航海時代の始まりでポルトガルがアフリカ西岸を南下した動機の一つとなった／マリ王国にかわってソンガイ王国が栄え、トンブクトゥが内陸アフリカのイスラームの学問の中心となった
