d|ビザンツ皇帝ユスティニアヌスが、ヴァンダル王国・東ゴート王国を滅ぼし、地中海世界をほぼ再統一した。『ローマ法大全』を編纂させ、ハギア=ソフィア聖堂を建てた。中国から養蚕技術を取り入れた。
c|西ローマ帝国の滅亡後、旧領にゲルマン人の王国が建てられていた。ローマ帝国の復興をめざした
r|戦争による財政負担で、死後に領土は縮小した。イタリアはランゴバルド人に奪われ（568〜）、ローマ教会はビザンツ皇帝の保護をあてにできなくなった
