c|聖像禁止令でビザンツ皇帝と対立した教皇が、ピピンが王位につくこと（751）を認めた見返り／トゥール・ポワティエ間の戦い以来、フランク王国がキリスト教世界の守り手と見られていた／ランゴバルド王国の圧迫を受けた教皇がフランク王国に保護を求めた
