P|リチャード1世|在位1189〜1199|イギリス|11
d|イギリス（プランタジネット朝）の王。獅子心王と呼ばれる。第3回十字軍に参加しサラーフ=アッディーンと戦った。
x|十字軍、アイユーブ朝とイェルサレム奪回
