P|フィリップ4世|在位1285〜1314|フランス|11
d|カペー朝のフランス王。三部会を開いて国内の支持を得、聖職者への課税に反対した教皇ボニファティウス8世をとらえた（アナーニ事件）。教皇庁をアヴィニョンに移した。
