c|フランス革命の始まり以後の革命戦争での苦戦と、パリ民衆による王宮襲撃（8月10日事件）による王権の停止／ルイ16世の処刑後、イギリスのピットの提唱で第1回対仏大同盟が結ばれ（1793）、国内ではヴァンデーの反乱などが起きた
r|封建地代の無償廃止で農民が自作農となり、徴兵制・革命暦・メートル法が導入された／独裁への反発からテルミドールのクーデタ（1794）でロベスピエールが処刑された。土地を得た農民は保守化し、総裁政府のもとで政治は不安定となって、ナポレオンの台頭を招いた
