d|ヴィクトリア女王の時代。自由党（グラッドストン）と保守党（ディズレーリ）の二大政党が交代して政権を担う議会政治が定着した。第2回（1867）・第3回（1884）選挙法改正で都市労働者・農業労働者に選挙権が広がった。
c|イギリスの自由主義的改革と、「世界の工場」としての経済的繁栄
r|教育法・労働組合法などの改革が進んだ／穀物法廃止とジャガイモ飢饉でアイルランドの農民が困窮し、アメリカへの移民が増えた。アイルランド自治問題が政治の大きな問題となった／スエズ運河会社株の買収（1875）やインド帝国の成立（1877）など、帝国主義の政策が始まった
p|ヴィクトリア女王、グラッドストン、ディズレーリ
