d|アメリカ合衆国が西へ領土を広げたこと。ルイジアナ買収（1803）、フロリダ買収（1819）、テキサス併合（1845）、アメリカ=メキシコ戦争（1846〜48）でカリフォルニアを獲得。「明白な天命（マニフェスト=デスティニー）」と正当化された。
