r|イギリスの縦断政策（カイロ・ケープタウン・カルカッタを結ぶ3C政策）とフランスの横断政策が衝突してファショダ事件（1898）が起きた／南アフリカ戦争（1899〜1902）／エチオピアはアドワの戦い（1896）でイタリアを破り独立を守った／ドイツのモロッコ進出でモロッコ事件（1905・1911）が起きた／民族や文化を無視した境界線が、独立後の紛争の原因にもなった
